import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"五分钟上手","description":"","frontmatter":{},"headers":[],"relativePath":"zh/quick-start.md","filePath":"zh/quick-start.md","lastUpdated":1793456875000}'),l={name:"zh/quick-start.md"};function i(d,t,s,n,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="五分钟上手" tabindex="-1">五分钟上手 <a class="header-anchor" href="#五分钟上手" aria-label="Permalink to &quot;五分钟上手&quot;">​</a></h1><p>本页用一段录好的示例面试演示 MeetCue 的完整效果，让你在真实会议前先熟悉面板。不需要 API 密钥，也不需要麦克风。</p><h2 id="启动演示" tabindex="-1">启动演示 <a class="header-anchor" href="#启动演示" aria-label="Permalink to &quot;启动演示&quot;">​</a></h2><ol><li><p>如果 MeetCue 正在运行，先退出（右键托盘图标 › <strong>退出 MeetCue</strong>）。</p></li><li><p>按 <code>Win+R</code>，输入下面的命令并回车：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MeetCue.exe --demo</span></span></code></pre></div><p>如果 Windows 找不到程序，请使用完整路径。通过 Scoop 安装时路径为 <code>%USERPROFILE%\\scoop\\apps\\meetcue\\current\\MeetCue.exe</code>。</p></li><li><p>面板出现在屏幕右侧并带有 <strong>演示</strong> 标记，稍后自动开始回放。按 <code>Ctrl+Alt+Space</code> 可暂停和继续。</p></li></ol><h2 id="你会看到什么" tabindex="-1">你会看到什么 <a class="header-anchor" href="#你会看到什么" aria-label="Permalink to &quot;你会看到什么&quot;">​</a></h2><p>演示回放的是一场网络工程岗位的面试。注意面板的这几个部分：</p><ol><li><strong>问题卡片</strong>：面试官问完一个问题约一秒半后，出现一张卡片，灰色的是问题原文，下方是编号要点。</li><li><strong>要点</strong>：每条要点由加粗的主词和几个灰色补充词组成。候选人讲到某条要点时，它会打上绿勾并变暗；下一条要讲的要点带 <strong>接下来</strong> 标签并高亮。</li><li><strong>其他问题</strong>：候选人回答时面试官插话提出的新问题，会以一行的形式显示在当前问题下方，标为 <strong>待回答</strong>，当前提示不会被替换。点击任意一行即可完整显示该问题。</li><li><strong>底栏</strong>：最近一次提示的延迟。点击可打开延迟探测。</li></ol><h2 id="试试快捷键" tabindex="-1">试试快捷键 <a class="header-anchor" href="#试试快捷键" aria-label="Permalink to &quot;试试快捷键&quot;">​</a></h2><p>演示进行时试试下面的快捷键。即使焦点在其他程序上，它们也有效。</p><table tabindex="0"><thead><tr><th>快捷键</th><th>动作</th></tr></thead><tbody><tr><td><code>Ctrl+Alt+Space</code></td><td>开始 / 暂停拾取</td></tr><tr><td><code>Ctrl+Alt+H</code></td><td>面板：完整 → 迷你条 → 隐藏</td></tr><tr><td><code>Ctrl+Alt+[</code> / <code>Ctrl+Alt+]</code></td><td>上一问 / 下一问</td></tr><tr><td><code>Ctrl+Alt+Enter</code></td><td>把当前问题标为已答</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>在<a href="/meetcue/zh/setup">首次设置</a>中配置供应商。</li><li>阅读<a href="/meetcue/zh/guide/meeting">会议模式</a>，了解问题如何被检测和排队。</li><li>不用开会，通过麦克风在<a href="/meetcue/zh/guide/mock-interview">模拟面试</a>中把整个流程试一遍。</li><li>在<a href="/meetcue/zh/guide/practice">练习模式</a>中用自己的题目演练。</li></ul>',12)])])}const g=e(l,[["render",i]]);export{u as __pageData,g as default};
